# ==============================================================================# 059_SQLITE_CONCURRENCY_PATCH.py# ==============================================================================import sqlite3from pathlib import PathROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB)cur = conn.cursor()print("="*80)print("SQLITE PATCH")print("="*80)cur.execute("PRAGMA journal_mode=WAL")print("Journal :", cur.fetchone()[0])cur.execute("PRAGMA synchronous=NORMAL")cur.execute("PRAGMA busy_timeout=30000")conn.commit()conn.close()print("busy_timeout : 30000 ms")print("Modo WAL     : ATIVADO")print("="*80)

